<script setup lang="ts">
definePageMeta({middleware:'auth'})
import { estimatePhotoCount, photoEstimateSizeMb } from '~/utils/photoCapacity'
const client=useSupabaseClient(),dialog=useAppDialog()
const plans=ref<any[]>([]),error=ref(''),busy=ref(false)
async function api<T>(url:string,opts:any={}){const {data:{session}}=await client.auth.getSession();if(!session)throw new Error('Sign in required');return $fetch<T>(url,{...opts,headers:{...opts.headers,authorization:`Bearer ${session.access_token}`}})}
async function load(){error.value='';try{plans.value=(await api<{plans:any[]}>('/api/admin/packages')).plans.map(p=>({...p,storage_mb:Math.round(p.storage_limit_bytes/1048576),existing:true}))}catch(e:any){error.value=e?.data?.statusMessage||e.message}}
function add(){plans.value.push({id:'',display_name:'',storage_mb:1024,retention_days:365,price_cents:0,currency:'AUD',active:false,sort_order:plans.value.length*10})}
async function save(p:any){if(busy.value)return;busy.value=true;error.value='';try{await api('/api/admin/packages',{method:'POST',body:{...p,storage_limit_bytes:Math.round(Number(p.storage_mb)*1048576),retention_days:p.retention_days===''?null:Number(p.retention_days),price_cents:Number(p.price_cents),sort_order:Number(p.sort_order)}});dialog.show('Package saved. New purchases will use the updated settings. Existing entitlements are unchanged.','success');await load()}catch(e:any){error.value=e?.data?.statusMessage||e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><main class="mx-auto max-w-5xl space-y-6 px-5 py-10"><NuxtLink to="/dashboard" class="ek-back-button inline-flex items-center gap-2 rounded-lg border border-[#D6B077] bg-[#FFFDF8] px-4 py-2 text-sm font-semibold text-[#0C1D2D] shadow-sm transition hover:bg-[#F0E5D3] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#B18A50]"><span aria-hidden="true">←</span><span>Back</span></NuxtLink><div class="flex items-center justify-between"><h1 class="text-3xl font-bold">Package Administration</h1><button class="btn" @click="add">Add package</button></div><p class="text-sm text-[#536273]">Admin-only. Changes affect future purchases; existing paid event allowances are preserved.</p><p v-if="error" class="text-red-700" role="alert">{{error}}</p><article v-for="(p,i) in plans" :key="i" class="panel grid gap-3 md:grid-cols-3"><label class="text-sm">Package ID<input v-model="p.id" class="input mt-1 w-full" :disabled="!!p.existing" placeholder="e.g. corporate" /></label><label class="text-sm">Name<input v-model="p.display_name" class="input mt-1 w-full" /></label><label class="text-sm">Storage (MB)<input v-model.number="p.storage_mb" type="number" min="1" class="input mt-1 w-full" /></label><div class="text-sm text-[#536273] md:col-span-3">Estimated capacity: <strong class="text-[#0C1D2D]">{{estimatePhotoCount(Number(p.storage_mb)*1048576).toLocaleString('en-AU')}} photos</strong> <span class="text-xs">(approximately {{photoEstimateSizeMb}} MB each; excludes videos)</span></div><label class="text-sm">Retention days<input v-model.number="p.retention_days" type="number" min="1" class="input mt-1 w-full" /></label><label class="text-sm">Price (cents)<input v-model.number="p.price_cents" type="number" min="0" class="input mt-1 w-full" /></label><label class="text-sm">Currency<input v-model="p.currency" class="input mt-1 w-full" maxlength="3" /></label><label class="text-sm">Display order<input v-model.number="p.sort_order" type="number" min="0" class="input mt-1 w-full" /></label><label class="flex items-center gap-2 text-sm"><input v-model="p.active" type="checkbox" /> Available for purchase</label><button class="btn" :disabled="busy" @click="save(p)">Save package</button></article></main></template>
